<?php use App\Core\Authorization;?>
<div class="sports-head"><div><h1>Quadras, horários e disponibilidade</h1><p>Configure cada espaço, seus dias, horários, intervalos, preços e bloqueios individualmente.</p></div><?php if(Authorization::allows('sports.manage')):?><a class="btn btn-primary" href="/sports/courts/create">+ Nova quadra</a><?php endif;?></div>
<div class="sports-grid"><?php foreach($courts as $c):?><article class="sports-court-card"><?php if($c['photo_path']):?><img src="<?=htmlspecialchars($c['photo_path'])?>" alt=""><?php else:?><div class="sports-photo-placeholder">🏟️</div><?php endif;?><div class="p-3"><div class="d-flex justify-content-between gap-2"><h2 class="h5"><?=htmlspecialchars($c['name'])?></h2><span class="sports-status <?=$c['active']?'status-confirmed':'status-cancelled'?>"><?=$c['active']?'Ativa':'Inativa'?></span></div><p class="text-secondary mb-2"><?=htmlspecialchars($c['unit_name']??'Sem unidade')?> · <?=htmlspecialchars($c['surface']??'Piso não informado')?></p><p><?=htmlspecialchars($c['modalities']??'Sem modalidade')?></p><small>Duração: <?=(int)$c['minimum_minutes']?> a <?=(int)$c['maximum_minutes']?> min<?php if($c['interval_minutes']):?> · intervalo <?=(int)$c['interval_minutes']?> min<?php endif;?></small><?php if(Authorization::allows('sports.manage')):?><a class="btn btn-outline-primary w-100 mt-3" href="/sports/courts/<?=(int)$c['id']?>/edit">Configurar horários e quadra</a><?php endif;?></div></article><?php endforeach;?><?php if(!$courts):?><div class="sports-empty">Cadastre a primeira quadra para liberar a agenda esportiva.</div><?php endif;?></div>
